//! Quest-side records: QUST, INFO, SCEN, QMDL.
//!
//! See [`super`] for the fixture conventions shared by every module here.

use crate::common::{assert_fully_decoded, assert_record_type, decode_fixture};
use serde_json::{Value, json};

/// INFO 0x0000219A — `<no edid>` — basic decode regression.
#[test]
fn info_dialog_response_decodes_correctly() {
    let result = decode_fixture(
        "INFO",
        195,
        &[
            ("ENAM", "0000010000000000"),
            ("GNAM", "9e210000"),
            ("TRDA", "ffffffff0100000000000000ffffffffffffffff"),
            (
                "NAM1",
                "3c49443d30303033384139443e2a736967682a2049277665206e65766572207365656e2061206368696c6420736f2072656c756374616e742061626f757420706c61792074696d652e00",
            ),
            ("NAM2", "00"),
            ("NAM3", "00"),
            ("NAM4", "00"),
            ("NAM9", "c0081683ec78d201"),
            (
                "CTDA",
                "002111e40000803f3602c94300000000000000000000000000000000ffffffff",
            ),
            (
                "CTDA",
                "002111e40000803f3b00c94364000000000000000000000000000000ffffffff",
            ),
            (
                "CTDA",
                "002111e4000000003b00c94358020000000000000000000000000000ffffffff",
            ),
            ("NAM0", "00"),
            ("INAM", "01000000"),
            ("NAM8", "10664c00362cd401"),
        ],
    );

    assert_record_type(&result, "Dialog response");
    assert_fully_decoded(&result);
}

/// QMDL 0x006496AB — `<no edid>` — basic decode regression.
#[test]
fn qmdl_object_destruction_decodes_correctly() {
    let result = decode_fixture(
        "QMDL",
        197,
        &[
            ("EDID", "4f626a6563744465737472756374696f6e00"),
            ("QMDI", "0000"),
            ("QMDQ", "ff5d6400"),
            ("QMDP", "005e6400"),
            ("QMDT", "100e"),
            ("QMPO", "0000"),
            ("QMAD", "00000000"),
            ("QMSD", "00000000"),
        ],
    );

    assert_record_type(&result, "Quest Module");
    assert_fully_decoded(&result);
}

/// QUST 0x000011F0 — `GQ_WorkshopReclaim` — alias fill-type + scoped PresentSignature regression.
